CREATE INDEX "purchases_google_reconciliation_idx" ON "purchases" USING btree ("store","lastReconciledAt","expiresDate") WHERE "purchases"."store" = 'PLAY_STORE' AND "purchases"."status" IN ('TRIAL', 'ACTIVE', 'GRACE_PERIOD', 'PAUSED');